          const j = db.insert('jobs', { ...v, customer: $('#sm', b).value, no: db.nextNo('jobs', PRE), code: H.kod(), status: cfg.firstStatus || 'planli', duration: Number(v.duration) || 60, lines: sv && Number(sv.price) ? [{ name: sv.name, qty: 1, price: Number(sv.price) }] : [], payments: [], checks: (sv && sv.checks ? String(sv.checks) : cfg.checks || '').split('\n').map((t) => t.trim()).filter(Boolean).map((t) => ({ t, ok: false })), log: [{ at: new Date().toISOString(), status: cfg.firstStatus || 'planli', note: `${JOB} açıldı`, user: NS.currentUser && NS.currentUser.name }] });
