        const bek = H.onaysiz(j); if (cfg.kilit && bek.length && !(await confirm(`Müşterinin onaylamadığı ${money(sum(bek, H.satir))} tutarında kalem var. Onaysız bitirilsin mi?`, { title: 'Müşteri onayı yok', ok: 'Onaysız bitir', danger: false }))) return; if (cfg.kilit && bek.length) log(j, j.status, `Onaysız kalemle bitirildi: ${money(sum(bek, H.satir))}`);
