    function fotoKarti(j) { const L = j.photos || []; return kart(`Fotoğraflar (${L.length})`, `<div class="card-b">${L.length ? `<div class="sh-foto">${L.map((u, i) => `<div><img src="${esc(u)}" alt="İş fotoğrafı ${i + 1}" loading="lazy"><button class="btn sm ghost icon" data-frm="${i}" title="Fotoğrafı sil" aria-label="Fotoğrafı sil">${icon('x')}</button></div>`).join('')}</div>` : '<div class="faint small">Fotoğraf eklenmedi</div>'}<input class="input mt" type="file" id="ff" accept="image/*" multiple aria-label="Fotoğraf seç"></div>`); }
    function isDetay(el, id, app) {
      const j = db.get('jobs', id); if (!j) return app.go('isler'); if (benim() && j.team !== benim()) return app.go('bugun'); j.log = j.log || []; const c = cust(j.customer); const ar = c.phone ? `<a class="btn sm" href="tel:${esc(c.phone)}">${icon('phone')} Ara</a>` : ''; const adres = j.addr || c.address || '';
      el.innerHTML = `<div class="row mb"><a class="btn" href="#/isler">${icon('back')} ${esc(cfg.listLabel || 'İşler')}</a><h1 class="grow">${esc(j.no)} · ${esc(j.title || '')}</h1>${gecikti(j) ? badge('Gecikti', 'err') : ''}${durum(j)}</div>
        <div class="card pad mb"><div class="row">${dugmeler(j)}<span class="grow"></span><button class="btn" data-x="print">${icon('print')} ${esc(cfg.formLabel || 'Form')}</button><button class="btn" data-x="link">${icon('globe')} Takip bağlantısı</button>${yonetim() ? `<button class="btn" data-x="edit">${icon('edit')} Düzenle</button>${acik(j) || (cfg.oncesi || []).includes(j.status) ? `<button class="btn" data-st="iptal">İptal</button>` : ''}` : ''}</div></div>
        <div class="grid g-21"><div class="col" style="gap:0">
          ${kart('Bilgiler', `<div class="card-b grid g2"><div><div class="small muted">Müşteri</div><b>${esc(c.name)}</b><div class="small">${esc(c.phone || '')}</div>${ar}</div><div><div class="small muted">Zaman</div><b>${zaman(j)}</b><div class="small muted">${esc(team(j.team).name)}</div></div><div class="full" style="grid-column:1/-1"><div class="small muted">Adres</div>${esc(adres || '-')} ${adres ? `<a class="btn sm ghost" target="_blank" rel="noopener" href="${esc(harita(adres))}">${icon('map')} Yol tarifi</a>` : ''}</div>${j.note ? `<div class="full" style="grid-column:1/-1"><div class="small muted">Not</div>${esc(j.note)}</div>` : ''}${j.onWay || j.startedAt || j.finishedAt ? `<div class="full small muted" style="grid-column:1/-1">${j.onWay ? `Yola çıkış ${NS.time(j.onWay)} · ` : ''}${j.startedAt ? `Başlangıç ${NS.time(j.startedAt)} · ` : ''}${j.finishedAt ? `Bitiş ${NS.time(j.finishedAt)}` : ''}</div>` : ''}</div>`)}
          ${cfg.cards ? cfg.cards(j, x) : ''}${kontrolKarti(j)}${fiyat() ? kalemKarti(j) + odemeKarti(j) : ''}${kart('Saha raporu', `<div class="card-b"><textarea class="input" id="rp" rows="3" placeholder="Yapılan iş, görülen sorun, müşteriye not...">${esc(j.report || '')}</textarea><button class="btn sm mt" id="rps">Raporu kaydet</button></div>`)}${fotoKarti(j)}
        </div><div class="col" style="gap:0">
          ${j.issue ? `<div class="sh-note err mb">${icon('alert')} <span class="grow"><b>Müşteri bildirimi:</b> ${esc(j.issue.note)}<br><span class="small">${NS.dt(j.issue.at)}</span></span>${yonetim() && !j.issue.job ? `<button class="btn sm primary" data-x="retry">${cfg.retryLabel || 'Tekrar ziyaret aç'}</button>` : ''}</div>` : ''}
          ${j.retryUntil ? `<div class="sh-note mb">${icon('shield')} <span class="grow">Ücretsiz tekrar süresi: ${NS.date(j.retryUntil)}</span></div>` : ''}${j.retryOf ? `<div class="sh-note mb">${icon('refresh')} <span>Tekrar ziyareti: <a href="#/is/${esc(j.retryOf)}">önceki iş</a></span></div>` : ''}
          ${j.review ? `<div class="card pad mb"><div class="small muted">Müşteri puanı</div><div style="font-size:20px;color:#f59e0b">${'★'.repeat(j.review.stars)}<span style="color:var(--border)">${'★'.repeat(5 - j.review.stars)}</span></div>${j.review.text ? `<div class="small mt">${esc(j.review.text)}</div>` : ''}</div>` : ''}
          ${kart('Geçmiş', `<div class="card-b"><div class="sh-tl">${j.log.slice().reverse().map((l) => `<div style="--c:${(ST[l.status] || {}).color || 'var(--accent)'}"><b>${esc((ST[l.status] || {}).name || l.status)}</b><div class="small">${esc(l.note || '')}</div><div class="small faint">${NS.dt(l.at)}${l.user ? ' · ' + esc(l.user) : ''}</div></div>`).join('')}</div><div class="row nw mt"><input class="input" id="nt" placeholder="Not ekle..." aria-label="Not ekle"><button class="btn" id="nts" aria-label="Notu kaydet">${icon('plus')}</button></div></div>`)}
          <div class="card pad center"><div class="small muted mb">Müşteri takip kodu</div><div class="mono" style="font-size:22px;font-weight:800;letter-spacing:.1em">${esc(j.code)}</div><div class="mt">${NS.qrSvg(trackUrl(j.code), 110)}</div></div>
        </div></div>`;
      on(el, 'click', '[data-st]', (e, b) => durumDegis(j, b.dataset.st, app));
      on(el, 'change', '[data-ck]', (e, b) => { j.checks[b.dataset.ck].ok = b.checked; db.save(); });
      on(el, 'click', '[data-x]', async (e, b) => { const k = b.dataset.x; if (k === 'print') yazdir(j); else if (k === 'link') { try { await navigator.clipboard.writeText(trackUrl(j.code)); toast('Takip bağlantısı kopyalandı', 'ok'); } catch (e2) { NS.prompt('Takip bağlantısı', trackUrl(j.code)); } } else if (k === 'edit') { const v = await formModal({ title: `${JOB} düzenle`, fields: isAlanlari(j), values: j, size: 'wide' }); if (!v || !(await cakismaOnay(v, j.id))) return; db.update('jobs', j.id, { ...v, duration: Number(v.duration) || 60 }); yenile(app); } else if (k === 'retry') { const y = tekrarAc(j); app.go('is', y.id); } });
      on(el, 'click', '[data-act=lrm]', (e, b) => { const l = j.lines[b.dataset.id]; if (cfg.kilit && l.ok) return toast('Onaylanan kalem silinemez', 'err'); if (l.pid) { const p = db.get('items', l.pid); if (p) p.stock = (Number(p.stock) || 0) + Number(l.qty); } j.lines.splice(b.dataset.id, 1); if (j.offer && j.offer.status === 'bekliyor') { const t = sum(H.onaysiz(j), H.satir); if (t) j.offer.total = t; else delete j.offer; } db.save(); yenile(app); });
      on(el, 'click', '[data-lt]', async (e, b) => {
        if (b.dataset.lt === 'kalem') { const v = await formModal({ title: 'Kalem ekle', fields: [{ name: 'name', label: 'Kalem', required: true, list: servisler().map((s) => s.name) }, { name: 'qty', label: 'Adet', type: 'number', step: '0.01', value: 1, required: true }, { name: 'price', label: 'Birim fiyat (₺)', type: 'number', step: '0.01', required: true }] }); if (!v) return; j.lines = j.lines || []; j.lines.push({ name: v.name, qty: Number(v.qty), price: Number(v.price) }); }
        else { const it = db.all('items'); if (!it.length) return toast('Önce stok kartı ekleyin', 'warn'); const v = await formModal({ title: 'Stoktan ekle', fields: [{ name: 'pid', label: 'Ürün', type: 'select', options: it.map((p) => ({ value: p.id, label: `${p.name} (stok ${p.stock || 0})` })) }, { name: 'qty', label: 'Adet', type: 'number', step: '0.01', value: 1, required: true }] }); if (!v) return; const p = db.get('items', v.pid); if ((Number(p.stock) || 0) < Number(v.qty) && !(await confirm(`${p.name} stokta yetersiz (${p.stock || 0}). Yine de eklensin mi?`, { ok: 'Ekle', danger: false }))) return; p.stock = (Number(p.stock) || 0) - Number(v.qty); j.lines = j.lines || []; j.lines.push({ pid: p.id, name: p.name, qty: Number(v.qty), price: Number(p.price) || 0 }); }
        if (j.offer && j.offer.status === 'bekliyor') j.offer.total = sum(H.onaysiz(j), H.satir); db.save(); yenile(app); });
      on(el, 'click', '[data-of]', async (e, b) => { const k = b.dataset.of; const kim = (NS.currentUser && NS.currentUser.name) || 'Panel';
        if (k === 'ac') { Object.assign(j, H.teklifAc(j, kim)); db.save(); bildir(c, `${S().bizName}: ${j.no} teklifiniz hazır (${money(j.offer.total)}). İnceleyip onaylayın: ${trackUrl(j.code)}`, 'Teklif bildirimi'); return yenile(app); }
        if (k === 'link') return bildir(c, `${S().bizName}: ${j.no} teklifi onayınızı bekliyor: ${trackUrl(j.code)}`, 'Teklif bildirimi');
        const not = k === 'red' ? await NS.prompt('Red nedeni', '', { title: 'Teklif reddedildi' }) : ''; if (not === null) return; if (k === 'onay' && !(await confirm('Müşterinin onay verdiği kayda geçecek. Devam edilsin mi?', { ok: 'Onaylandı', danger: false }))) return; Object.assign(j, H.teklifCevap(j, k, `${kim} (panel)`, not)); db.save(); yenile(app); });
      on(el, 'click', '[data-pay]', async (e, b) => { const k = b.dataset.pay; if (k === 'fatura') return isFatura(j, app); const v = await formModal({ title: { kapora: 'Kapora al', iade: 'İade yap', tahsilat: 'Tahsilat' }[k], fields: [{ name: 'amount', label: 'Tutar', type: 'number', step: '0.01', required: true }, { name: 'type', label: 'Ödeme', type: 'select', options: ODEME }, ...(k === 'iade' ? [{ name: 'why', label: 'Neden', required: true, full: true }] : [])], values: { amount: k === 'tahsilat' ? Math.max(0, H.kalan(j)) : '' } }); if (!v) return; if (!(Number(v.amount) > 0)) return toast('Tutar girin', 'err'); if (k === 'iade' && Number(v.amount) > H.odenen(j)) return toast('İade, ödenenden büyük olamaz', 'err'); j.payments = j.payments || []; j.payments.push({ type: v.type, amount: Number(v.amount), at: new Date().toISOString(), kind: k, ...(v.why ? { why: v.why } : {}) }); log(j, j.status, `${{ kapora: 'Kapora', iade: 'İade', tahsilat: 'Tahsilat' }[k]}: ${money(v.amount)}${v.why ? ' · ' + v.why : ''}`); db.save(); yenile(app); });
      $('#rps', el).onclick = () => { j.report = $('#rp', el).value.trim(); db.save(); toast('Rapor kaydedildi', 'ok'); };
      $('#nts', el).onclick = () => { const v = $('#nt', el).value.trim(); if (!v) return; log(j, j.status, v); db.save(); yenile(app); };
      on(el, 'click', '[data-frm]', (e, b) => { const old = [...(j.photos || [])]; j.photos.splice(b.dataset.frm, 1); if (NS.dosya.birak) NS.dosya.birak(db, old, j.photos); db.save(); yenile(app); });
      $('#ff', el).onchange = async (e) => { await NS.dosya.toplu(e.target, [...e.target.files], async (f) => { if ((j.photos || []).length >= 12) { toast('Bir işte en fazla 12 fotoğraf', 'err'); return false; } const h = await NS.dosya.hazirla(db, f, { sinir: 250 * 1024 }); j.photos = j.photos || []; j.photos.push(await h.yukle()); }); db.save(); yenile(app); };
      if (cfg.bind) cfg.bind(el, j, x, app);
    }
    async function isFatura(j, app) { if (j.invoice) return toast(`Bu işe belge kesildi: ${j.invoice}`, 'warn'); const c = cust(j.customer); const r = await NS.ebelge.create({ docType: 'auto', buyer: c.name, buyerVkn: c.taxNo, address: j.addr || c.address, no: j.no, lines: (j.lines || []).map((l) => ({ name: l.name, qty: Number(l.qty), price: Number(l.price), vat: Number(S().vat) || 0 })), note: j.title }); if (r && r.no) { j.invoice = r.no + (r.simulated ? ' (TEST)' : ''); log(j, j.status, `e-Belge ${j.invoice}`); db.save(); yenile(app); } else if (r && r.error) toast('Belge oluşturulamadı: ' + r.error, 'err'); }
    // Müşteri bildirimi veya ücretsiz tekrar: yeni iş açılır, eskisi tekrar sayılmaz
    function tekrarAc(j) { const uc = !j.retryUntil || j.retryUntil >= today(); const y = db.insert('jobs', { customer: j.customer, title: `${j.title || ''} (tekrar)`, addr: j.addr, date: today(), duration: j.duration, team: j.team, no: db.nextNo('jobs', PRE), code: H.kod(), status: 'planli', lines: [], payments: [], checks: (j.checks || []).map((c) => ({ t: c.t, ok: false })), retryOf: j.id, plan: '', ...(cfg.retryExtra ? cfg.retryExtra(j) : {}), log: [{ at: new Date().toISOString(), status: 'planli', note: `Tekrar ziyareti · ${j.no}${uc ? ' · ücretsiz süre içinde' : ' · ücretsiz süre geçti'}` }] }); if (j.issue) j.issue.job = y.id; log(j, j.status, `Tekrar ziyareti açıldı: ${y.no}`); db.save(); return y; }

    // ---------- Listeler ----------
    function parcali(el, id, rows, ciz) { let n = SAYFA; const go = () => { $('#' + id, el).innerHTML = ciz(rows.slice(0, n)) + (rows.length > n ? `<div class="center pad"><button class="btn" data-more>${rows.length - n} kayıt daha göster</button></div>` : ''); const m = $(`#${id} [data-more]`, el); if (m) m.onclick = () => { n += SAYFA * 2; go(); }; }; go(); }
    function isListe(el, p, app) {
      let q = '', f = 'acik', tf = ''; const pre = (cfg.listFilters || []);
      el.innerHTML = pageHead(cfg.listLabel || 'İşler', cfg.listSub || 'Tüm işler, arama ve dışa aktarma', `<button class="btn" id="ex">${icon('download')} CSV</button>${yonetim() ? `<button class="btn primary" id="ni">${icon('plus')} Yeni ${esc(JOB.toLocaleLowerCase('tr'))}</button>` : ''}`) + `<div class="card"><div class="card-h">${NS.searchBox('q', 'No, müşteri, telefon, hizmet...')}<select class="input" id="tf" style="max-width:180px" aria-label="${esc(TEAM)}"><option value="">Tüm ekipler</option>${ekipler().map((t) => `<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select><div class="seg">${[['acik', 'Açık'], ...pre, ['bugun', 'Bugün'], ['gec', 'Geciken'], ['tamam', 'Biten'], ['hepsi', 'Tümü']].map(([v, l]) => `<button data-f="${v}" class="${v === f ? 'active' : ''}">${esc(l)}</button>`).join('')}</div></div><div id="t"></div></div>`;
      const satirlar = () => { const C = adlar('customers'); const bu = today(); const pf = pre.find(([v]) => v === f); return db.all('jobs', (j) => { if (benim() && j.team !== benim()) return false; if (tf && j.team !== tf) return false; if (pf ? !pf[2](j) : f === 'acik' ? !acik(j) && !(cfg.oncesi || []).includes(j.status) : f === 'bugun' ? j.date !== bu : f === 'gec' ? !gecikti(j) : f === 'tamam' ? j.status !== 'tamam' : false) return false; const c = C.get(j.customer) || {}; return NS.match(q, j.no, j.title, c.name, c.phone, j.addr); }).sort((a, b) => String(f === 'hepsi' || f === 'tamam' ? b.date : a.date).localeCompare(String(f === 'hepsi' || f === 'tamam' ? a.date : b.date))); };
      const ciz = () => { const r = satirlar(); const C = adlar('customers'), T = adlar('teams'); parcali(el, 't', r, (L) => table({ rows: L, emptyIcon: 'wrench', empty: 'Bu görünümde kayıt yok', mobileCard: (j) => `<div class="row between nw"><b>${esc(j.no)}</b>${durum(j)}</div><div>${esc(j.title || '')}</div><div class="small muted">${esc(ismi(C, j.customer))} · ${zaman(j)}</div>`, columns: [{ label: 'No', render: (j) => `<a href="#/is/${esc(j.id)}"><b>${esc(j.no)}</b></a>` }, { label: 'Tarih', render: (j) => zaman(j) }, { label: 'Müşteri', render: (j) => esc(ismi(C, j.customer)) }, { label: 'Hizmet', render: (j) => esc(j.title || '') }, { label: TEAM, render: (j) => esc(ismi(T, j.team)) }, { label: 'Durum', render: (j) => `${durum(j)}${gecikti(j) ? ' ' + badge('Gecikti', 'err') : ''}` }, ...(fiyat() ? [{ label: 'Tutar', cls: 'right', render: (j) => money(H.toplam(j)) }] : [])], actions: [{ icon: 'eye', act: 'v', title: 'Aç' }] }) + `<div class="tbl-foot small muted">${r.length} kayıt</div>`); };
      $('#q', el).oninput = (e) => { q = e.target.value; ciz(); }; $('#tf', el).onchange = (e) => { tf = e.target.value; ciz(); };
      on(el, 'click', '[data-f]', (e, b) => { f = b.dataset.f; $$('[data-f]', el).forEach((k) => k.classList.toggle('active', k === b)); ciz(); }); on(el, 'click', '[data-act=v]', (e, b) => app.go('is', b.dataset.id));
      if ($('#ni', el)) $('#ni', el).onclick = () => isFormu(app); $('#ex', el).onclick = () => { const C = adlar('customers'); NS.csv(`${cfg.id}-isler`, satirlar(), [{ key: 'no', label: 'No' }, { key: 'date', label: 'Tarih' }, { label: 'Müşteri', value: (j) => ismi(C, j.customer) }, { key: 'title', label: 'Hizmet' }, { label: 'Durum', value: (j) => (ST[j.status] || {}).name }, ...(fiyat() ? [{ label: 'Tutar', value: H.toplam }] : [])]); }; ciz();
    }
    function bugun(el, p, app) {
      const bu = today(); const ben = benim(); const L = db.all('jobs', (j) => (ben ? j.team === ben : true) && (j.date === bu || (j.date <= bu && j.dateTo >= bu) || gecikti(j)) && !H.KAPALI.includes(j.status)).sort((a, b) => String(a.time || '99').localeCompare(String(b.time || '99'))); const C = adlar('customers');
      el.innerHTML = pageHead(cfg.todayLabel || 'Bugünkü İşler', NS.dateLong(new Date()), yonetim() ? `<button class="btn primary" id="ni">${icon('plus')} Yeni ${esc(JOB.toLocaleLowerCase('tr'))}</button>` : '') + (L.length ? `<div class="sh-gun">${L.slice(0, 200).map((j) => { const c = C.get(j.customer) || {}; return `<div class="card pad"><div class="row between nw"><a href="#/is/${esc(j.id)}"><b>${esc(j.time || 'Saat yok')}${j.timeTo ? '–' + esc(j.timeTo) : ''} · ${esc(j.title || j.no)}</b></a>${durum(j)}</div><div class="small muted">${esc(c.name || '-')} · ${esc(j.addr || c.address || '')}</div>${gecikti(j) ? `<div class="mt">${badge('Gecikti: ' + NS.date(j.date), 'err')}</div>` : ''}<div class="row mt">${c.phone ? `<a class="btn sm" href="tel:${esc(c.phone)}">${icon('phone')} Ara</a>` : ''}<a class="btn sm" target="_blank" rel="noopener" href="${esc(harita(j.addr || c.address))}">${icon('map')} Yol tarifi</a><span class="grow"></span><a class="btn sm primary" href="#/is/${esc(j.id)}">Aç</a></div></div>`; }).join('')}</div>` : `<div class="card"><div class="empty">${icon('calendar')}<div>Bugün için iş yok</div></div></div>`);
      if ($('#ni', el)) $('#ni', el).onclick = () => isFormu(app);
    }
    function takvim(el, p, app) {
      let bas = H.haftaBas(today()); let dragId = null;
      const ciz = () => { planUret(); const gunler = Array.from({ length: 7 }, (_, i) => H.ekle(bas, i)); const son = gunler[6]; const ben = benim(); const J = db.all('jobs', (j) => j.date && j.date <= son && (j.dateTo || j.date) >= bas && !['iptal', 'red'].includes(j.status) && (!ben || j.team === ben)); const C = adlar('customers'); const sat = [...ekipler().filter((t) => !ben || t.id === ben), ...(ben ? [] : [{ id: '', name: 'Atanmadı' }])];
        const hucre = (t, d) => J.filter((j) => (j.team || '') === t.id && j.date <= d && (j.dateTo || j.date) >= d).sort((a, b) => String(a.time).localeCompare(String(b.time))).map((j) => `<a class="sh-is" draggable="true" data-j="${esc(j.id)}" href="#/is/${esc(j.id)}" style="--c:${(ST[j.status] || {}).color}"><b>${esc(j.time || '')}</b> ${esc((C.get(j.customer) || {}).name || '')}<span>${esc(j.title || '')}</span></a>`).join('');
        el.innerHTML = pageHead(cfg.calLabel || 'Ekip Takvimi', 'İşi sürükleyip başka gün veya ekibe taşıyın', `<button class="btn" id="on" aria-label="Önceki hafta">${icon('left')}</button><button class="btn" id="bu">Bu hafta</button><button class="btn" id="so" aria-label="Sonraki hafta">${icon('right')}</button>`) + `<div class="card"><div class="tbl-wrap"><table class="sh-cal"><thead><tr><th>${esc(TEAM)}</th>${gunler.map((d, i) => `<th class="${d === today() ? 'bu' : ''}">${H.GUNLER[i]} ${esc(d.slice(8))}.${esc(d.slice(5, 7))}</th>`).join('')}</tr></thead><tbody>${sat.map((t) => `<tr><th>${esc(t.name)}</th>${gunler.map((d) => `<td data-g="${d}" data-t="${esc(t.id)}">${hucre(t, d)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;
        $('#on', el).onclick = () => { bas = H.ekle(bas, -7); ciz(); }; $('#so', el).onclick = () => { bas = H.ekle(bas, 7); ciz(); }; $('#bu', el).onclick = () => { bas = H.haftaBas(today()); ciz(); }; };
      el.addEventListener('dragstart', (e) => { const c = e.target.closest('[data-j]'); if (c) dragId = c.dataset.j; }); el.addEventListener('dragover', (e) => { if (dragId && e.target.closest('[data-g]')) e.preventDefault(); });
      el.addEventListener('drop', async (e) => { const h = e.target.closest('[data-g]'); if (!h || !dragId) return; e.preventDefault(); const j = db.get('jobs', dragId); dragId = null; const fark = H.gunFarki(h.dataset.g, j.date); const v = { date: h.dataset.g, dateTo: j.dateTo ? H.ekle(j.dateTo, fark) : '', team: h.dataset.t, time: j.time, duration: j.duration, status: j.status }; if (!(await cakismaOnay({ ...j, ...v }, j.id))) return; Object.assign(j, v); log(j, j.status, `Taşındı: ${NS.date(v.date)} · ${team(v.team).name}`); db.save(); ciz(); });
      ciz();
    }

    // ---------- Sözleşme ve üretim ----------
    const planlar = () => db.all('contracts');
    // Yalnız yönetim üretir. Ufuk ayardadır; üretim tekrar çalışsa da aynı gün ikinci kez yazılmaz.
